"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[175],{1442:(a,e,o)=>{o.d(e,{cn:()=>i});function i(...a){return a.filter(Boolean).join(" ")}},2379:(a,e,o)=>{o.d(e,{_:()=>i,r:()=>n});let i={name:"NOCTUA",legalName:"NOCTUA Salud Mental SpA",rut:"77.441.890-2",tagline:"Lo que no se duerme.",description:"Centro de salud mental en Las Condes. Psicolog\xeda cl\xednica y psiquiatr\xeda. Cincuenta minutos, la misma persona. Abrimos a las 16:00. \xdaltimo cupo 22:00.",url:"https://noctuasalud.cl",email:"hora@noctuasalud.cl",phone:"+56 2 3288 4770",phoneHref:"tel:+56232884770",mobile:"+56 9 7612 4770",mobileHref:"tel:+56976124770",whatsapp:"+56 9 7612 4770",whatsappHref:"https://wa.me/56976124770?text=Hola%20NOCTUA%2C%20quiero%20pedir%20una%20primera%20hora.",instagram:"https://instagram.com/noctua.salud",instagramHandle:"@noctua.salud",coords:{lat:"33\xb024′S",lng:"70\xb035′W"},geo:{lat:-33.408,lng:-70.588},address:{line1:"Los Militares 4770",commune:"Las Condes",city:"Santiago",region:"Regi\xf3n Metropolitana",country:"Chile",maps:"https://maps.google.com/?q=Los+Militares+4770+Las+Condes"},metro:"Escuela Militar \xb7 8 min a pie",parking:"Seis cupos en el predio \xb7 aviso al agendar",hoursShort:"Lun–Vie 16:00–23:00 \xb7 S\xe1b 10:00–14:00",hours:[{days:"Lunes a viernes",time:"16:00 – 23:00"},{days:"S\xe1bado",time:"10:00 – 14:00"},{days:"Domingo y festivos",time:"Cerrado"}],lastSlot:"22:00",openHour:16,closeHour:23,saturdayOpen:10,saturdayClose:14,founded:2019,crisis:{label:"Si ahora es demasiado",line:"Salud Responde 600 360 7777 \xb7 *4141 prevenci\xf3n del suicidio",phone:"600 360 7777",phoneHref:"tel:6003607777",alt:"*4141",altHref:"tel:*4141"}},n=[{href:"/enfoque",label:"Enfoque"},{href:"/areas",label:"\xc1reas"},{href:"/equipo",label:"Equipo"},{href:"/noche",label:"La noche"}]},2381:(a,e,o)=>{o.d(e,{IO:()=>t,Q0:()=>s,bn:()=>i,gv:()=>r,kL:()=>l,tO:()=>n});let i=[{slug:"ansiedad",n:"01",title:"Ansiedad y p\xe1nico",thought:"El pecho no abre.",forWhom:"El pecho que no abre, la lista que no termina, el ataque que llega en la micro o a las tres de la ma\xf1ana.",duration:"50 min",priceFrom:48e3,image:"/images/lamp.jpg",alt:"L\xe1mpara \xe1mbar encendida sobre mesa de roble en una sala oscura",lead:"No es falta de voluntad. Es un sistema de alarma que se qued\xf3 encendido.",body:"De d\xeda el p\xe1nico se disfraza de productividad. De noche, si alguien sabe mirar, se nombra. Trabajamos el cuerpo y el pensamiento juntos: lo que pasa en el pecho, lo que la cabeza anticipa, lo que se evita. No hay frases de calma gen\xe9ricas. Hay un mapa de tus alarmas y un plan para apagarlas sin apagarte.",includes:["Evaluaci\xf3n del patr\xf3n de alarma","Herramientas para el momento del ataque","Trabajo entre sesiones, no tarea escolar","Derivaci\xf3n a psiquiatr\xeda si el cuerpo lo pide"],star:{x:112,y:96}},{slug:"animo",n:"02",title:"\xc1nimo y depresi\xf3n",thought:"El d\xeda no arranca.",forWhom:"El d\xeda que se hace largo. La cama que no suelta. Lo que se llama flojera y no lo es.",duration:"50 min",priceFrom:48e3,image:"/images/ventana.jpg",alt:"Ventana alta hacia Santiago de noche, cortina oscura y un filo de luz \xe1mbar",lead:"No te vamos a pedir que te levantes con una frase. Vamos a nombrar lo que pesa.",body:"Depresi\xf3n, distimia, el baj\xf3n que ya no es coyuntural. Coordinamos con psiquiatr\xeda cuando hay indicaci\xf3n de f\xe1rmaco — no como atajo, como parte del mismo plan. El alta no es ‘ya sonre\xedste’. El ritmo de las sesiones se acomoda a la energ\xeda real, no a un calendario de pack.",includes:["Lectura cl\xednica, no coaching","Ritmo de sesiones seg\xfan energ\xeda real","Trabajo con sue\xf1o, apetito y aislamiento","Psiquiatr\xeda en la misma casa, si hace falta"],star:{x:208,y:96}},{slug:"duelo",n:"03",title:"Duelo y p\xe9rdida",thought:"Lo que falta no se va.",forWhom:"Una muerte, una separaci\xf3n, un cuerpo que cambi\xf3, un pa\xeds que se fue.",duration:"50 min",priceFrom:48e3,image:"/images/object.jpg",alt:"Cuaderno oscuro, l\xe1piz y frasco \xe1mbar bajo una sola luz",lead:"El duelo no se cierra. Se aprende a habitar con lo que falta.",body:"P\xe9rdidas que el entorno ya no nombra. Duelos no autorizados, abortos, migraciones, el padre que se fue sin irse. Aqu\xed hay tiempo. No hay etapas de afiche. La noche, a menudo, es cuando el muerto vuelve a la casa: esa hora tambi\xe9n se trabaja.",includes:["Espacio para lo que no se dice afuera","Rituales posibles, no recetas","Trabajo con el cuerpo del duelo","Acompa\xf1amiento el tiempo que tome"],star:{x:160,y:138}},{slug:"trauma",n:"04",title:"Trauma",thought:"El cuerpo recuerda.",forWhom:"Lo que el cuerpo recuerda aunque la cabeza ya no quiera.",duration:"50 min",priceFrom:54e3,image:"/images/still.jpg",alt:"Cuaderno abierto y l\xe1piz de grafito sobre piedra oscura",lead:"No se trata de revivir. Se trata de que el presente deje de ser el pasado.",body:"Trauma simple y complejo. EMDR cuando corresponde, trabajo som\xe1tico cuando el relato no alcanza. Nunca se fuerza una escena. Si el caso necesita otro nivel de cuidado, lo decimos en la primera hora. El cupo de las 22:00 existe tambi\xe9n para esto: hay recuerdos que solo aparecen cuando la ciudad se apaga.",includes:["Evaluaci\xf3n de seguridad antes de intervenir","EMDR y abordaje som\xe1tico, seg\xfan caso","Ritmo del paciente, no del protocolo","Red de derivaci\xf3n si hace falta internaci\xf3n"],star:{x:160,y:48}},{slug:"pareja",n:"05",title:"Pareja y v\xednculo",thought:"Ya no se oyen.",forWhom:"Dos que ya no se escuchan. O uno que quiere y otro que duda.",duration:"60 min",priceFrom:64e3,image:"/images/dialogo.jpg",alt:"Dos sillones de lino marfil frente a frente en una sala nocturna",lead:"No venimos a decidir si se quedan. Venimos a que se oigan sin lastimarse.",body:"Terapia de pareja y de v\xednculo. Sesenta minutos. La misma terapeuta. Si hay violencia, se nombra y se detiene el formato de pareja: no se ‘trabaja el conflicto’ encima de un golpe. Los cupos de pareja son de 18:00 a 22:00: despu\xe9s del trabajo, no en vez del trabajo.",includes:["Sesi\xf3n de 60 minutos","Marco claro de respeto en la sala","Trabajo con el patr\xf3n, no con la \xfaltima pelea","Individuales puntuales si el caso lo pide"],star:{x:128,y:208}},{slug:"infanto",n:"06",title:"Infanto-juvenil",thought:"El ni\xf1o avisa.",forWhom:"Ni\xf1os y adolescentes. Y los padres que ya no saben c\xf3mo entrar.",duration:"50 min",priceFrom:5e4,image:"/images/jardin.jpg",alt:"Jard\xedn nocturno visto desde el interior, a trav\xe9s del vidrio",lead:"El ni\xf1o no es el problema. Es el que est\xe1 avisando.",body:"Juego, palabra, colegio, casa. Trabajamos con la familia sin convertir la sesi\xf3n en un tribunal. Adolescentes: un espacio que no es de los padres y no es de Instagram. Los cupos infanto son de 16:00 a 19:00 y el s\xe1bado. Si hay riesgo, se act\xfaa — no se espera el lunes.",includes:["Primera hora con los cuidadores","Sesiones con el ni\xf1o o adolescente","Devoluci\xf3n clara a la familia","Coordinaci\xf3n con colegio, si ustedes lo piden"],star:{x:192,y:208}},{slug:"sueno",n:"07",title:"Sue\xf1o y rumiaci\xf3n",thought:"Las tres de la ma\xf1ana.",forWhom:"Las tres de la ma\xf1ana. El caf\xe9 que ya no hace nada. El burnout que se disfraza de productividad.",duration:"50 min",priceFrom:48e3,image:"/images/hero.jpg",alt:"Sala de consulta nocturna: un sill\xf3n de lino, una l\xe1mpara, Santiago al otro lado",lead:"Dormir no es un premio. Es la base. Si no est\xe1, el resto se desarma.",body:"Insomnio, hipersomnia, la rumiaci\xf3n que no apaga. Higiene de sue\xf1o sin moralina. El pensamiento de las tres no se trata de d\xeda: se nombra a la hora en que ocurre, o se mapea para que deje de mandar. Si hay indicaci\xf3n farmacol\xf3gica, la psiquiatra de la casa entra al plan.",includes:["Mapa de sue\xf1o de quince d\xedas","Trabajo con rumiaci\xf3n nocturna","L\xedmites laborales nombrados, no sermoneados","Psiquiatr\xeda si el insomnio ya es cl\xednico"],star:{x:52,y:164}},{slug:"psiquiatria",n:"08",title:"Psiquiatr\xeda",thought:"Cuando el f\xe1rmaco cabe.",forWhom:"Cuando el f\xe1rmaco cabe — y cuando hay que decir que no cabe.",duration:"45–50 min",priceFrom:64e3,image:"/images/mesa.jpg",alt:"Taza de t\xe9 y una hoja sobre mesa de roble oscuro",lead:"Recetar es f\xe1cil. Indicar con criterio, y acompa\xf1ar, es el oficio.",body:"Primera evaluaci\xf3n psiqui\xe1trica y controles. Trabaja en la misma casa que el equipo de psicolog\xeda: no hay dos fichas, no hay dos versiones. Si el f\xe1rmaco no suma, se baja. Si suma, se explica en cristiano. Los controles caben despu\xe9s de las 18:00.",includes:["Primera evaluaci\xf3n de 50 minutos","Controles de 45 minutos","Coordinaci\xf3n con tu terapeuta NOCTUA","Informe para ISAPRE, si lo pides"],star:{x:268,y:164}}],n=[["trauma","ansiedad"],["trauma","animo"],["ansiedad","duelo"],["animo","duelo"],["duelo","pareja"],["duelo","infanto"],["pareja","infanto"],["sueno","ansiedad"],["sueno","pareja"],["psiquiatria","animo"],["psiquiatria","infanto"]],s=["16:00","17:00","18:00","19:00","20:00","21:00","22:00"],r=[{slug:"catalina-errazuriz",name:"Catalina Err\xe1zuriz",credential:"Psiquiatra \xb7 Universidad de Chile",extra:"Directora cl\xednica \xb7 adulto",focus:"Psiquiatr\xeda",areas:["psiquiatria","animo","ansiedad"],line:"Recetar es f\xe1cil. Indicar con criterio es el oficio.",image:"/images/catalina.jpg",bio:"Dirige la casa. Ve adultos. Coordina cada caso que cruza f\xe1rmaco y palabra para que no haya dos versiones de la misma persona. Formada en la Universidad de Chile, con rotaci\xf3n en hospital p\xfablico y consulta privada desde 2012. Atiende de 17:00 a 22:00."},{slug:"tomas-vidal",name:"Tom\xe1s Vidal",credential:"Psic\xf3logo cl\xednico \xb7 UDP",extra:"Ansiedad, p\xe1nico, agotamiento",focus:"Ansiedad",areas:["ansiedad","sueno"],line:"El pecho que no abre no se arregla con una app.",image:"/images/tomas.jpg",bio:"Trabaja con ansiedad, p\xe1nico y el agotamiento de quien rinde. Terapia cognitivo-conductual y trabajo con el cuerpo de la alarma. Atiende presencial y online, de 16:00 a 22:00. Universidad Diego Portales, mag\xedster en psicolog\xeda cl\xednica."},{slug:"magdalena-rojas",name:"Magdalena Rojas",credential:"Psic\xf3loga cl\xednica \xb7 Universidad de Chile",extra:"Duelo, trauma, EMDR",focus:"Trauma",areas:["duelo","trauma"],line:"El duelo no se cierra. Se aprende a habitar.",image:"/images/magdalena.jpg",bio:"Duelo y trauma. EMDR certificado. No fuerza escenas. El ritmo lo pone quien llega, no el protocolo. Universidad de Chile. Trabaja con adultos y con duelos que el entorno ya no nombra. Cupos hasta las 21:00."},{slug:"ignacio-pena",name:"Ignacio Pe\xf1a",credential:"Psic\xf3logo cl\xednico \xb7 Pontificia Universidad Cat\xf3lica",extra:"\xc1nimo, depresi\xf3n, sue\xf1o",focus:"\xc1nimo",areas:["animo","sueno"],line:"No te vamos a pedir que te levantes con una frase.",image:"/images/ignacio.jpg",bio:"\xc1nimo, depresi\xf3n y el insomnio que las acompa\xf1a. Trabaja en t\xe1ndem con la psiquiatra de la casa cuando hay indicaci\xf3n de f\xe1rmaco. PUC. Consulta lenta, precisa, sin coaching. \xdaltimo cupo 22:00."},{slug:"antonia-silva",name:"Antonia Silva",credential:"Psic\xf3loga cl\xednica \xb7 Universidad de Chile",extra:"Infanto-juvenil",focus:"Infanto-juvenil",areas:["infanto"],line:"El ni\xf1o no es el problema. Es el que est\xe1 avisando.",image:"/images/antonia.jpg",bio:"Ni\xf1os y adolescentes. Juego, palabra, colegio, casa. Primera hora con los cuidadores; despu\xe9s, un espacio que no es tribunal. Cupos de 16:00 a 19:00 y s\xe1bados. Si hay riesgo, act\xfaa el mismo d\xeda. Universidad de Chile, formaci\xf3n infanto-juvenil."},{slug:"josefina-araya",name:"Josefina Araya",credential:"Psic\xf3loga cl\xednica \xb7 Universidad de los Andes",extra:"Pareja, familia, v\xednculo",focus:"Pareja",areas:["pareja"],line:"No venimos a decidir si se quedan. Venimos a que se oigan.",image:"/images/josefina.jpg",bio:"Pareja y familia. Sesenta minutos. Si hay violencia, se nombra y se detiene el formato. Universidad de los Andes, formaci\xf3n sist\xe9mica. Atiende tambi\xe9n a quienes llegan solos a hablar de un v\xednculo que no cierra. Cupos de 18:00 a 22:00."}],l=[{q:"\xbfPor qu\xe9 abren de noche?",a:"Porque el pensamiento no cierra a las 18. Quien trabaja no puede perder la ma\xf1ana en una sala de espera. Quien rumia a las tres necesita un cupo que exista despu\xe9s de las 20:00. Lun a vie, 16:00 a 23:00. \xdaltimo cupo 22:00. S\xe1bado, 10:00 a 14:00."},{q:"\xbfCu\xe1nto cuesta la primera hora?",a:"La primera hora psicol\xf3gica dura 50 minutos y vale $54.000. Incluye emparejamiento, hip\xf3tesis y un ritmo tentativo. El valor de las sesiones siguientes se confirma ese d\xeda. Psiquiatr\xeda primera: $78.000. Tel\xe9fono: +56 2 3288 4770."},{q:"\xbfAtienden ISAPRE y FONASA?",a:"Emitimos boleta reembolsable el mismo d\xeda. Particular e ISAPRE (Banm\xe9dica, Colmena, Consalud, Cruz Blanca, Nueva Masvida, Vida Tres y otras). FONASA: te orientamos con el c\xf3digo; el porcentaje lo define tu plan, no lo prometemos. El reembolso lo gestiona tu ISAPRE, no nosotros."},{q:"\xbfPresencial u online?",a:"Las dos. La casa est\xe1 en Los Militares 4770, Las Condes, a ocho minutos de Metro Escuela Militar. Online por videollamada, mismo valor, mismo terapeuta. La primera hora preferimos presencial cuando se puede: el cuerpo habla distinto en la sala."},{q:"\xbfMe asignan al que tenga hora?",a:"No. Leemos lo que escribes y te proponemos una persona — y te decimos por qu\xe9. Si no calza en las primeras dos sesiones, se cambia de terapeuta sin costo de emparejamiento. El hueco no manda."},{q:"\xbfCu\xe1nto dura un tratamiento?",a:"Lo decide el trabajo, no un pack. Algunos procesos cierran en meses; otros se quedan. Cada cierto tramo revisamos: qu\xe9 cambi\xf3, qu\xe9 no, si sigue teniendo sentido. No hay veinte sesiones por adelantado."},{q:"\xbfQu\xe9 pasa si ahora es una crisis?",a:"Esta casa no es urgencia ni hospital. Si hay riesgo vital, llama a Salud Responde 600 360 7777 o al *4141 (prevenci\xf3n del suicidio). Si est\xe1s en NOCTUA y aparece un riesgo, actuamos el mismo d\xeda: la ficha no espera al lunes."},{q:"\xbfC\xf3mo cancelo o cambio una hora?",a:"Por WhatsApp o al +56 2 3288 4770, con 24 horas de anticipaci\xf3n. Menos que eso, se cobra la sesi\xf3n: el cupo es de una persona. Responde el equipo, no un call center. Si no contestamos, devolvemos el llamado el mismo d\xeda h\xe1bil."},{q:"\xbfLa ficha es confidencial?",a:"S\xed. Secreto profesional. No se informa a empleadores, parejas ni colegios sin tu consentimiento, salvo las excepciones legales (riesgo vital, orden judicial). La ficha se conserva seg\xfan la normativa sanitaria chilena."}],t=["Particular","Banm\xe9dica","Colmena","Consalud","Cruz Blanca","Esencial","Nueva Masvida","Vida Tres","FONASA","Otra"]},5985:(a,e,o)=>{o.r(e),o.d(e,{Reveal:()=>r});var i=o(5155),n=o(2115),s=o(1442);function r({children:a,className:e,delay:o=0}){let l=(0,n.useRef)(null);return(0,n.useEffect)(()=>{let a=l.current;if(!a)return;if(window.matchMedia("(prefers-reduced-motion: reduce)").matches)return void a.classList.add("is-visible");let e=new IntersectionObserver(([o])=>{o.isIntersecting&&(a.classList.add("is-visible"),e.disconnect())},{threshold:.16,rootMargin:"0px 0px -8% 0px"});return e.observe(a),()=>e.disconnect()},[]),(0,i.jsx)("div",{ref:l,className:(0,s.cn)("reveal",e),style:{transitionDelay:`${o}ms`},children:a})}}}]);